impl TableCmdSetTableSelection {
    pub fn dump(&self, out: &mut String, t: &Tables) {
        out.push('{');
        out.push_str("anchor:");
        uo_codec::dump::u(out, self.anchor);
        out.push_str(",path:");
        out.push('[');
        for (i0, e0) in self.path.iter().enumerate() {
            if i0 > 0 { out.push(','); }
            e0.dump(out, t);
        }
        out.push(']');
        out.push_str(",rect:");
        self.rect.dump(out, t);
        out.push_str(",origin:");
        self.origin.dump(out, t);
        out.push('}');
    }
}

