impl ClipboardCmd {
    pub fn dump(&self, out: &mut String, t: &Tables) {
        match self {
            Self::Copy => out.push_str("Copy"),
            Self::Cut => out.push_str("Cut"),
            Self::Paste(v) => {
                out.push_str("Paste(");
                v.dump(out, t);
                out.push(')');
            }
            Self::PasteData(v) => {
                out.push_str("PasteData(");
                v.dump(out, t);
                out.push(')');
            }
            Self::PasteText(v) => {
                out.push_str("PasteText(");
                v.dump(out, t);
                out.push(')');
            }
            Self::Repaste(v) => {
                out.push_str("Repaste(");
                v.dump(out, t);
                out.push(')');
            }
            Self::PasteCells(v) => {
                out.push_str("PasteCells(");
                v.dump(out, t);
                out.push(')');
            }
            Self::PasteSpecialFormats => out.push_str("PasteSpecialFormats"),
            Self::PasteSpecial(v) => {
                out.push_str("PasteSpecial(");
                v.dump(out, t);
                out.push(')');
            }
            Self::PasteClipboardItem(v) => {
                out.push_str("PasteClipboardItem(");
                v.dump(out, t);
                out.push(')');
            }
            Self::PasteAllClipboardItems(v) => {
                out.push_str("PasteAllClipboardItems(");
                v.dump(out, t);
                out.push(')');
            }
            Self::RemoveClipboardItem(v) => {
                out.push_str("RemoveClipboardItem(");
                v.dump(out, t);
                out.push(')');
            }
            Self::ClearClipboardItems => out.push_str("ClearClipboardItems"),
            Self::SetDocumentPath(v) => {
                out.push_str("SetDocumentPath(");
                v.dump(out, t);
                out.push(')');
            }
            Self::SetPasteDefaults(v) => {
                out.push_str("SetPasteDefaults(");
                v.dump(out, t);
                out.push(')');
            }
            Self::SetInlineTypes(v) => {
                out.push_str("SetInlineTypes(");
                v.dump(out, t);
                out.push(')');
            }
            Self::AddLinkSource(v) => {
                out.push_str("AddLinkSource(");
                v.dump(out, t);
                out.push(')');
            }
            Self::PasteLinkWith(v) => {
                out.push_str("PasteLinkWith(");
                v.dump(out, t);
                out.push(')');
            }
        }
    }

    pub fn random(rng: &mut Rng, b: &Bounds, depth: u32) -> Self {
        match rng.below(18) {
            0 => Self::Copy,
            1 => Self::Cut,
            2 => Self::Paste(ClipboardCmdPaste::random(rng, b, depth + 1)),
            3 => Self::PasteData(ClipboardCmdPasteData::random(rng, b, depth + 1)),
            4 => Self::PasteText(ClipboardCmdPasteText::random(rng, b, depth + 1)),
            5 => Self::Repaste(ClipboardCmdRepaste::random(rng, b, depth + 1)),
            6 => Self::PasteCells(ClipboardCmdPasteCells::random(rng, b, depth + 1)),
            7 => Self::PasteSpecialFormats,
            8 => Self::PasteSpecial(ClipboardCmdPasteSpecial::random(rng, b, depth + 1)),
            9 => Self::PasteClipboardItem(ClipboardCmdPasteClipboardItem::random(rng, b, depth + 1)),
            10 => Self::PasteAllClipboardItems(ClipboardCmdPasteAllClipboardItems::random(rng, b, depth + 1)),
            11 => Self::RemoveClipboardItem(ClipboardCmdRemoveClipboardItem::random(rng, b, depth + 1)),
            12 => Self::ClearClipboardItems,
            13 => Self::SetDocumentPath(ClipboardCmdSetDocumentPath::random(rng, b, depth + 1)),
            14 => Self::SetPasteDefaults(ClipboardCmdSetPasteDefaults::random(rng, b, depth + 1)),
            15 => Self::SetInlineTypes(ClipboardCmdSetInlineTypes::random(rng, b, depth + 1)),
            16 => Self::AddLinkSource(ClipboardCmdAddLinkSource::random(rng, b, depth + 1)),
            _ => Self::PasteLinkWith(ClipboardCmdPasteLinkWith::random(rng, b, depth + 1)),
        }
    }
}

