impl TabOnly {
    pub fn dump(&self, out: &mut String, t: &Tables) {
        out.push('{');
        out.push_str("add:");
        match &self.add {
            Some(v) => {
                out.push('[');
                for (i0, e0) in v.iter().enumerate() {
                    if i0 > 0 { out.push(','); }
                    e0.dump(out, t);
                }
                out.push(']');
            }
            None => out.push('-'),
        }
        out.push_str(",remove:");
        match &self.remove {
            Some(v) => {
                out.push('[');
                for (i0, e0) in v.iter().copied().enumerate() {
                    if i0 > 0 { out.push(','); }
                    uo_codec::dump::f64(out, e0);
                }
                out.push(']');
            }
            None => out.push('-'),
        }
        out.push('}');
    }
}

impl TabOnly {
    pub fn random(rng: &mut Rng, b: &Bounds, depth: u32) -> Self {
        Self {
            add: if rng.bool() { Some({ let n = if depth > 3 { 0 } else if depth == 0 && rng.below(48) == 0 { 130 + rng.below(100) } else { rng.below(4) }; (0..n).map(|_| TabStopInfo::random(rng, b, depth + 1)).collect::<Vec<_>>() }) } else { None },
            remove: if rng.bool() { Some({ let n = if depth > 3 { 0 } else if depth == 0 && rng.below(48) == 0 { 130 + rng.below(100) } else { rng.below(4) }; (0..n).map(|_| rng.f64_edge()).collect::<Vec<_>>() }) } else { None },
        }
    }
}

