impl PicColor {
    pub fn dump(&self, out: &mut String, t: &Tables) {
        out.push('{');
        out.push_str("kind:");
        uo_codec::dump::utf16(out, &self.kind);
        out.push_str(",val:");
        uo_codec::dump::utf16(out, &self.val);
        out.push_str(",last_clr:");
        match &self.last_clr {
            Some(v) => {
                uo_codec::dump::utf16(out, v);
            }
            None => out.push('-'),
        }
        out.push_str(",mods:");
        match &self.mods {
            Some(v) => {
                out.push('[');
                for (i0, e0) in v.iter().enumerate() {
                    if i0 > 0 { out.push(','); }
                    e0.dump(out, t);
                }
                out.push(']');
            }
            None => out.push('-'),
        }
        out.push('}');
    }
}

impl PicColor {
    pub fn random(rng: &mut Rng, b: &Bounds, depth: u32) -> Self {
        Self {
            kind: rng.utf16(6),
            val: rng.utf16(6),
            last_clr: if rng.bool() { Some(rng.utf16(6)) } else { None },
            mods: if rng.bool() { Some({ let n = if depth > 3 { 0 } else if depth == 0 && rng.below(48) == 0 { 130 + rng.below(100) } else { rng.below(4) }; (0..n).map(|_| TupUtf16F64::random(rng, b, depth + 1)).collect::<Vec<_>>() }) } else { None },
        }
    }
}

