impl FxFill {
    pub fn dump(&self, out: &mut String, t: &Tables) {
        out.push('{');
        out.push_str("type:");
        uo_codec::dump::utf16(out, &self.r#type);
        out.push_str(",color:");
        match &self.color {
            Some(v) => {
                v.dump(out, t);
            }
            None => out.push('-'),
        }
        out.push_str(",stops:");
        match &self.stops {
            Some(v) => {
                out.push('[');
                for (i0, e0) in v.iter().enumerate() {
                    if i0 > 0 { out.push(','); }
                    e0.dump(out, t);
                }
                out.push(']');
            }
            None => out.push('-'),
        }
        out.push_str(",lin:");
        match &self.lin {
            Some(v) => {
                v.dump(out, t);
            }
            None => out.push('-'),
        }
        out.push_str(",path:");
        match &self.path {
            Some(v) => {
                v.dump(out, t);
            }
            None => out.push('-'),
        }
        out.push('}');
    }
}

impl FxFill {
    pub fn random(rng: &mut Rng, b: &Bounds, depth: u32) -> Self {
        Self {
            r#type: rng.utf16(6),
            color: if rng.bool() { Some(FxColor::random(rng, b, depth + 1)) } else { None },
            stops: if rng.bool() { Some({ let n = if depth > 3 { 0 } else if depth == 0 && rng.below(48) == 0 { 130 + rng.below(100) } else { rng.below(4) }; (0..n).map(|_| FxGradStop::random(rng, b, depth + 1)).collect::<Vec<_>>() }) } else { None },
            lin: if rng.bool() { Some(FxLin::random(rng, b, depth + 1)) } else { None },
            path: if rng.bool() { Some(FxPath::random(rng, b, depth + 1)) } else { None },
        }
    }
}

