impl ChangeSet {
    pub fn dump(&self, out: &mut String, t: &Tables) {
        out.push('{');
        out.push_str("stories:");
        out.push('[');
        for (i0, e0) in self.stories.iter().enumerate() {
            if i0 > 0 { out.push(','); }
            e0.dump(out, t);
        }
        out.push(']');
        out.push_str(",selection:");
        self.selection.dump(out, t);
        out.push_str(",events:");
        out.push('[');
        for (i0, e0) in self.events.iter().enumerate() {
            if i0 > 0 { out.push(','); }
            e0.dump(out, t);
        }
        out.push(']');
        out.push_str(",dirty:");
        out.push_str(if self.dirty { "true" } else { "false" });
        out.push_str(",can_undo:");
        out.push_str(if self.can_undo { "true" } else { "false" });
        out.push_str(",can_redo:");
        out.push_str(if self.can_redo { "true" } else { "false" });
        out.push_str(",formatting:");
        out.push_str(if self.formatting { "true" } else { "false" });
        out.push('}');
    }
}

