impl StoryLoc {
    pub fn dump(&self, out: &mut String, t: &Tables) {
        match self {
            Self::Body => out.push_str("Body"),
            Self::Cell(v) => {
                out.push_str("Cell(");
                out.push('[');
                for (i0, e0) in v.iter().enumerate() {
                    if i0 > 0 { out.push(','); }
                    e0.dump(out, t);
                }
                out.push(']');
                out.push(')');
            }
            Self::Hf(v) => {
                out.push_str("Hf(");
                let v = *v;
                uo_codec::dump::u(out, v);
                out.push(')');
            }
            Self::Note(v) => {
                out.push_str("Note(");
                v.dump(out, t);
                out.push(')');
            }
        }
    }

    pub fn random(rng: &mut Rng, b: &Bounds, depth: u32) -> Self {
        match rng.below(4) {
            0 => Self::Body,
            1 => Self::Cell({ let n = if depth > 3 { 0 } else if depth == 0 && rng.below(48) == 0 { 130 + rng.below(100) } else { rng.below(4) }; (0..n).map(|_| CellStep::random(rng, b, depth + 1)).collect::<Vec<_>>() }),
            2 => Self::Hf(rng.u32_edge()),
            _ => Self::Note(StoryLocNote::random(rng, b, depth + 1)),
        }
    }
}

