impl QueryError {
    pub fn dump(&self, out: &mut String, t: &Tables) {
        match self {
            Self::Pattern => out.push_str("Pattern"),
            Self::Special(v) => {
                out.push_str("Special(");
                uo_codec::dump::utf16(out, v);
                out.push(')');
            }
            Self::Syntax(v) => {
                out.push_str("Syntax(");
                uo_codec::dump::utf16(out, v);
                out.push(')');
            }
            Self::Unsupported => out.push_str("Unsupported"),
        }
    }

    pub fn random(rng: &mut Rng, b: &Bounds, depth: u32) -> Self {
        match rng.below(4) {
            0 => Self::Pattern,
            1 => Self::Special(rng.utf16(6)),
            2 => Self::Syntax(rng.utf16(6)),
            _ => Self::Unsupported,
        }
    }
}

