impl RevisionStory {
    pub fn dump(&self, out: &mut String, t: &Tables) {
        match self {
            Self::Body => out.push_str("Body"),
            Self::Table => out.push_str("Table"),
            Self::Header => out.push_str("Header"),
            Self::Footer => out.push_str("Footer"),
            Self::Footnote => out.push_str("Footnote"),
            Self::Endnote => out.push_str("Endnote"),
        }
    }

    pub fn random(rng: &mut Rng, b: &Bounds, depth: u32) -> Self {
        match rng.below(6) {
            0 => Self::Body,
            1 => Self::Table,
            2 => Self::Header,
            3 => Self::Footer,
            4 => Self::Footnote,
            _ => Self::Endnote,
        }
    }
}

impl SpanProps {
    pub fn dump(&self, out: &mut String, t: &Tables) {
        match self {
            Self::Run(v) => {
                out.push_str("Run(");
                v.dump(out, t);
                out.push(')');
            }
            Self::Para(v) => {
                out.push_str("Para(");
                v.dump(out, t);
                out.push(')');
            }
        }
    }

    pub fn random(rng: &mut Rng, b: &Bounds, depth: u32) -> Self {
        match rng.below(2) {
            0 => Self::Run(RunProps::random(rng, b, depth + 1)),
            _ => Self::Para(ParaProps::random(rng, b, depth + 1)),
        }
    }
}

