impl Cols {
    pub fn dump(&self, out: &mut String, t: &Tables) {
        out.push('{');
        out.push_str("count:");
        uo_codec::dump::f64(out, self.count);
        out.push_str(",space_twips:");
        uo_codec::dump::f64(out, self.space_twips);
        out.push_str(",sep:");
        out.push_str(if self.sep { "true" } else { "false" });
        out.push_str(",widths:");
        match &self.widths {
            Some(v) => {
                out.push('[');
                for (i0, e0) in v.iter().enumerate() {
                    if i0 > 0 { out.push(','); }
                    e0.dump(out, t);
                }
                out.push(']');
            }
            None => out.push('-'),
        }
        out.push('}');
    }
}

impl Cols {
    pub fn random(rng: &mut Rng, b: &Bounds, depth: u32) -> Self {
        Self {
            count: rng.f64_edge(),
            space_twips: rng.f64_edge(),
            sep: rng.bool(),
            widths: if rng.bool() { Some({ let n = if depth > 3 { 0 } else if depth == 0 && rng.below(48) == 0 { 130 + rng.below(100) } else { rng.below(4) }; (0..n).map(|_| ColWidth::random(rng, b, depth + 1)).collect::<Vec<_>>() }) } else { None },
        }
    }
}

